import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"How to Protect Your Base","description":"","frontmatter":{},"headers":[],"relativePath":"info/claims.md","filePath":"info/claims.md"}'),s={name:"info/claims.md"};function i(n,e,l,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="how-to-protect-your-base" tabindex="-1">How to Protect Your Base <a class="header-anchor" href="#how-to-protect-your-base" aria-label="Permalink to &quot;How to Protect Your Base&quot;">​</a></h1><p>Never worry about other players breaking your house or stealing your chests. Use a golden shovel to claim your land.</p><hr><h2 id="how-to-claim-land" tabindex="-1">How to Claim Land <a class="header-anchor" href="#how-to-claim-land" aria-label="Permalink to &quot;How to Claim Land&quot;">​</a></h2><p>You start with <strong>100 free claim blocks</strong> when you first join. You automatically earn <strong>100 more claim blocks for every hour you play</strong> on the server.</p><ol><li>Hold a <strong>Golden Shovel</strong> in your hand (you get one in <code>/kit starter</code>).</li><li><strong>Right-click</strong> one corner of the area you want to protect. A diamond block will show up to mark your spot.</li><li>Walk across to the opposite corner and <strong>right-click</strong> the ground again.</li><li>Gold and glowstone blocks will light up around your border. Your base is now 100% protected!</li></ol><p>Nobody can break blocks, place blocks, or open your chests inside your claim.</p><hr><h2 id="letting-friends-inside-your-base" tabindex="-1">Letting Friends Inside Your Base <a class="header-anchor" href="#letting-friends-inside-your-base" aria-label="Permalink to &quot;Letting Friends Inside Your Base&quot;">​</a></h2><p>If you want to play with your friends, you can give them trust:</p><ul><li><strong>Full Trust</strong> (<code>/trust &lt;friend&gt;</code>): Lets your friend build, break blocks, and open all your chests.</li><li><strong>Chest Trust</strong> (<code>/containertrust &lt;friend&gt;</code>): Lets your friend open chests and furnaces, but they cannot break or place blocks.</li><li><strong>Door Trust</strong> (<code>/accesstrust &lt;friend&gt;</code>): Lets visitors open doors, gates, and press buttons without touching anything else.</li><li><strong>Remove Trust</strong> (<code>/untrust &lt;friend&gt;</code>): Takes away their access immediately.</li></ul><hr><h2 id="raid-events-base-shields" tabindex="-1">Raid Events &amp; Base Shields <a class="header-anchor" href="#raid-events-base-shields" aria-label="Permalink to &quot;Raid Events &amp; Base Shields&quot;">​</a></h2><p>LlamaCraft has fun weekend raid hours where teams can fight.</p><ul><li>Your base is safe during the week.</li><li>During scheduled raid hours, explosions are turned on.</li><li>If you are going offline and want your base completely safe, buy a shield using <code>/siegeshield</code>!</li></ul>',15)])])}const p=o(s,[["render",i]]);export{g as __pageData,p as default};
